      ta.style.cssText = "position:fixed; left:-9999px; top:-9999px;";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
      } catch (e) { }
      ta.remove();
      if (typeof showToast === "function")
        showToast("Playbook JSON copied to clipboard — paste into a .json file to save");
    };
    footer.appendChild(btnExport);
    var btnBack = document.createElement("button");
    btnBack.className = "btn-secondary";
    btnBack.style.cssText = "flex:1; min-width:0; font-size:10px;";
    btnBack.innerHTML = "← BACK";
    btnBack.onclick = function () {
      if (typeof window.showTrackChangesSettingsPopup === "function") window.showTrackChangesSettingsPopup();
    };
    footer.appendChild(btnBack);
    card.appendChild(footer);
    out.appendChild(card);
    renderEditor();
  });
}

functions._scanDocumentForPlaybook:
function _scanDocumentForPlaybook() {
  return Word.run(async function (context) {
    var paragraphs = context.document.body.paragraphs;
    paragraphs.load("text");
    await context.sync();
    var clauses = [];
    var clauseId = 0;
    for (var i = 0; i < paragraphs.items.length; i++) {
      var text = (paragraphs.items[i].text || "").trim();
      if (!text || text.length < 5) continue;
      var quotedStart = text.match(/^[""\u201C]([^""\u201D]+)[""\u201D]/);
      var firstSentence = text.match(/^[^.!?]+[.!?]?/);
      var sectionName = quotedStart
        ? quotedStart[0].trim()
        : firstSentence
          ? firstSentence[0].trim()
          : text.substring(0, 120);
      if (sectionName.length > 120) sectionName = sectionName.substring(0, 120) + "...";
      clauseId++;
      clauses.push({
        id: "clause_" + clauseId,
        articleId: "",
        sectionId: sectionName,
        sectionSubClause: "",
        text: text.substring(0, 3000),
        guidanceComment: "",
        lockClause: false,
        lockComment: "",
        fallbacks: [],
      });
    }
    return { clauses: clauses }
  });
}

functions._showBuildNewPlaybookFromDoc:
function _showBuildNewPlaybookFromDoc() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  var card = document.createElement("div");
  card.className = "tool-box slide-in";
  card.style.cssText = "padding:0; border-radius:0; border:1px solid #d1d5db; border-left:5px solid #c9a227; background:#fff;";
  var header = document.createElement("div");
  header.style.cssText = "background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%); padding:12px 15px; border-bottom:3px solid #c9a227;";
  header.innerHTML =
    '<div style="font-size:9px; font-weight:700; color:#8fa6c7; text-transform:uppercase; letter-spacing:2px; margin-bottom:2px;">PLAYBOOK BUILDER</div>' +
    '<div style="font-size:16px; color:#fff; display:flex; align-items:center; gap:8px;"><span style="font-size:18px;">📄</span> Build from Current Document</div>';
  card.appendChild(header);
  var bodyDiv = document.createElement("div");
  bodyDiv.style.cssText = "padding:20px;";
  var nameLabel = document.createElement("div");
  nameLabel.style.cssText = "font-size:10px; font-weight:800; color:#1e293b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;";
  nameLabel.textContent = "Agreement Type Name";
  bodyDiv.appendChild(nameLabel);
  var nameInput = document.createElement("input");
  nameInput.type = "text";
  nameInput.placeholder = "e.g. Research Agreement, NDA, Services Agreement...";
  nameInput.style.cssText = "width:100%; padding:10px 12px; font-size:12px; border:1px solid #cbd5e1; border-radius:0; box-sizing:border-box; margin-bottom:16px; font-family:'Segoe UI',system-ui,sans-serif;";
  var detectedType = (window._eliDocType || "").trim();
  if (detectedType) nameInput.value = detectedType;
  bodyDiv.appendChild(nameInput);
  var statusDiv = document.createElement("div");
  statusDiv.style.cssText = "font-size:11px; color:#64748b; margin-bottom:16px; min-height:20px;";
  statusDiv.textContent =
    "Click the button below to scan the current document. Each paragraph becomes a clause — the first sentence is used as the section name. You can assign articles in the editor.";
  bodyDiv.appendChild(statusDiv);
  var btnScan = document.createElement("button");
  btnScan.innerHTML = '<span style="margin-right:6px;">🔍</span> SCAN DOCUMENT';
  btnScan.style.cssText =
    "width:100%; padding:12px 16px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; cursor:pointer; " +
    "background:linear-gradient(135deg,#2563eb,#1d4ed8); color:#fff; border:1.5px solid #1d4ed8; border-radius:0; " +
    "font-family:'Segoe UI',system-ui,sans-serif; box-shadow:0 2px 8px rgba(37,99,235,0.25); margin-bottom:12px;";
  var previewDiv = document.createElement("div");
  previewDiv.style.cssText = "max-height:300px; overflow-y:auto; margin-bottom:16px;";
  var scanResult = null;
  btnScan.onclick = function () {
    var typeName = (nameInput.value || "").trim();
    if (!typeName) {
      if (typeof showToast === "function") showToast("Enter an agreement type name first.");
      nameInput.focus();
      return;
    }
    btnScan.disabled = true;
    btnScan.textContent = "Scanning...";
    statusDiv.textContent = "Scanning document paragraphs...";
    window
      ._scanDocumentForPlaybook()
      .then(function (result) {
        scanResult = result;
        var clauseCount = result.clauses.length;
        statusDiv.innerHTML =
          '<span style="color:#16a34a; font-weight:700;">Found ' +
          clauseCount +
          " paragraph" +
          (clauseCount !== 1 ? "s" : "") +
          ". Each becomes a clause. Assign articles in the editor after saving.</span>";
        previewDiv.innerHTML = "";
        var escP = function (s) {
          var d = document.createElement("div");
          d.appendChild(document.createTextNode(s || ""));
          return d.innerHTML;
        }
        result.clauses.forEach(function (cl, idx) {
          var preview = (cl.text || "").length > 100 ? cl.text.substring(0, 100) + "..." : cl.text;
          previewDiv.innerHTML +=
            '<div style="display:flex; gap:8px; padding:6px 8px; margin-bottom:4px; border:1px solid #e2e8f0; background:#fafbfc; align-items:flex-start;">' +
            '<span style="font-size:9px; font-weight:800; color:#94a3b8; min-width:20px; text-align:right;">' +
            (idx + 1) +
            "</span>" +
            '<div style="flex:1; min-width:0;">' +
            '<div style="font-size:10px; font-weight:700; color:#0f172a; margin-bottom:2px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">' +
            escP(cl.sectionId) +
            "</div>" +
            '<div style="font-size:9px; color:#64748b; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">' +
            escP(preview) +
            "</div>" +
            "</div></div>";
        });
        btnScan.disabled = false;
        btnScan.innerHTML = '<span style="margin-right:6px;">🔍</span> RE-SCAN DOCUMENT';
      })
      .catch(function (err) {
        statusDiv.textContent = "Scan failed. Make sure a document is open.";
        btnScan.disabled = false;
        btnScan.innerHTML = '<span style="margin-right:6px;">🔍</span> SCAN DOCUMENT';
      });
  }
  bodyDiv.appendChild(btnScan);
  bodyDiv.appendChild(previewDiv);
  var btnRow = document.createElement("div");
  btnRow.style.cssText = "display:flex; gap:8px;";
  var btnSaveOpen = document.createElement("button");
  btnSaveOpen.innerHTML = "SAVE & OPEN EDITOR";
  btnSaveOpen.style.cssText =
    "flex:1; padding:10px 16px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; " +
    "background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:1.5px solid #15803d; border-radius:0; font-family:'Segoe UI',system-ui,sans-serif;";
  btnSaveOpen.onclick = function () {
    var typeName = (nameInput.value || "").trim();
    if (!typeName) {
      if (typeof showToast === "function") showToast("Enter an agreement type name.");
      return;
    }
    if (!scanResult || !scanResult.clauses || scanResult.clauses.length === 0) {
      if (typeof showToast === "function") showToast("Scan the document first.");
      return;
    }
    var data = {
      playbookClauses: scanResult.clauses,
      clauseMapping: { libraryName: typeName, clauses: scanResult.clauses, articleGuidance: {} },
      uploadedAt: new Date().toISOString(),
    }
    window._savePlaybookForType(typeName, data).then(function () {
      if (typeof showToast === "function") showToast("Playbook saved for " + typeName + ". Opening editor...");
      setTimeout(function () {
        if (typeof window.showPlaybookBuilderApp === "function") window.showPlaybookBuilderApp(typeName);
      }, 400);
    });
  }
  btnRow.appendChild(btnSaveOpen);
  var btnExportJson = document.createElement("button");
  btnExportJson.innerHTML = "COPY JSON";
  btnExportJson.style.cssText =
    "padding:10px 16px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; " +
    "background:linear-gradient(135deg,#6366f1,#4f46e5); color:#fff; border:1.5px solid #4f46e5; border-radius:0; font-family:'Segoe UI',system-ui,sans-serif;";
  btnExportJson.onclick = function () {
    if (!scanResult || !scanResult.clauses || scanResult.clauses.length === 0) {
      if (typeof showToast === "function") showToast("Scan the document first.");
      return;
    }
    var typeName = (nameInput.value || "").trim() || "Untitled";
    var exportData = { libraryName: typeName, clauses: scanResult.clauses, articleGuidance: {} }
    var ta = document.createElement("textarea");
    ta.value = JSON.stringify(exportData, null, 2);
    ta.style.cssText = "position:fixed; left:-9999px;";
    document.body.appendChild(ta);
    ta.select();
    document.execCommand("copy");
    document.body.removeChild(ta);
    if (typeof showToast === "function") showToast("Playbook JSON copied to clipboard.");
    btnExportJson.textContent = "✅ COPIED";
    setTimeout(function () {
      btnExportJson.innerHTML = "COPY JSON";
    }, 2000);
  }
  btnRow.appendChild(btnExportJson);
  bodyDiv.appendChild(btnRow);
  var btnBack = document.createElement("button");
  btnBack.innerHTML = "◀ BACK";
  btnBack.style.cssText =
    "width:100%; margin-top:8px; padding:8px 16px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; " +
    "background:linear-gradient(135deg,#e8ecf1,#d1d5db); color:#1b263b; border:1.5px solid #9ca3af; border-radius:0;";
  btnBack.onclick = function () {
    if (typeof window.showPlaybookBuilderApp === "function") window.showPlaybookBuilderApp();
  }
  bodyDiv.appendChild(btnBack);
  card.appendChild(bodyDiv);
  out.appendChild(card);
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // Playbook persistence via eli.storage. STORE_PLAYBOOKS = "playbooks".
  // Each playbook row has {id: agreementType, ...clauseMapping, ...}.
  // Same shape v2's playbook DB used.

  // _loadTrackPortPlaybooks() → Promise<{type: playbook}>
  // Returns a map keyed by agreement type. Empty object on miss or error.
  if (typeof window._loadTrackPortPlaybooks !== "function") {
    window._loadTrackPortPlaybooks = function () {
      return eli.storage.getAll("playbooks").then(function (rows) {
        var map = {};
        (rows || []).forEach(function (entry) {
          if (entry && entry.id) map[entry.id] = entry;
        });
        return map;
      }).catch(function () { return {}; });
    };
  }

  // _savePlaybookForType(type, data) → Promise<void>
  // Stamps data.id = type and puts it. Caller's `data` keeps its other
  // fields (clauses, articleGuidance, libraryName).
  if (typeof window._savePlaybookForType !== "function") {
    window._savePlaybookForType = function (type, data) {
      var entry = Object.assign({}, data, { id: type });
      return eli.storage.put("playbooks", entry);
    };
  }

  // _deletePlaybookForType(type) → Promise<void>
  if (typeof window._deletePlaybookForType !== "function") {
    window._deletePlaybookForType = function (type) {
      return eli.storage.delete("playbooks", type);
    };
  }

  // ─── Tile handler ────────────────────────────────────────────────
  function _open(agreementType) {
    if (typeof window.showPlaybookBuilderApp !== "function") {
      if (typeof showToast === "function") showToast("Playbook Manager failed to load — try Data Hub → Force re-install.", "err");
      return;
    }
    try { window.showPlaybookBuilderApp(agreementType); }
    catch (e) {
      eli.log.event("tool", "playbook_manager_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Playbook Manager failed: " + (e && e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_playbook_manager: _open },
    playbook_manager: { open: _open },
  });

  eli.log.event("tool", "playbook_manager_initialized", {});
}
